experiment.py<pre><code>import pandas as pd
import numpy as np


class Experiment:
    def __init__(self, name, filepath):
        self.name = name
        self.filepath = filepath
        self.time = None
        self.signal = None
        self.stats = {}

    def load(self):
        data = pd.read_csv(self.filepath)
        self.time = data['time'].values
        self.signal = data['stress'].values

    def analyze(self):
        self.stats = {
            'mean': np.mean(self.signal),
            'std': np.std(self.signal),
            'peak': np.max(self.signal),
        }

    def summary(self):
        print(f"[{self.name}] "
              f"mean={self.stats['mean']:.2f}, "
              f"std={self.stats['std']:.2f}, "
              f"peak={self.stats['peak']:.2f}")
